async function waitForCompletion(sessionID, toolContext, ctx) {
  log4(`[call_omo_agent] Polling for completion...`);
  const POLL_INTERVAL_MS = 500;
  const MAX_POLL_TIME_MS = 5 * 60 * 1000;
  const PROMPT_ACCEPTANCE_TIMEOUT_MS = 30 * 1000;
  const pollStart = Date.now();
  let lastMsgCount = 0;
  let stablePolls = 0;
  const STABILITY_REQUIRED = 3;
  let sawActiveStatus = false;
  while (Date.now() - pollStart < MAX_POLL_TIME_MS) {
    if (toolContext.abort?.aborted) {
      log4(`[call_omo_agent] Aborted by user`);
      throw new Error("Task aborted.");
    }
    await new Promise((resolve) => setTimeout(resolve, POLL_INTERVAL_MS));
    const statusResult = await ctx.client.session.status();
    const allStatuses = normalizeSDKResponse(statusResult, {});
    const sessionStatus = allStatuses[sessionID];
    if (sessionStatus && sessionStatus.type !== "idle") {
      sawActiveStatus = true;
      stablePolls = 0;
      lastMsgCount = 0;
      continue;
    }
    const messagesCheck = await ctx.client.session.messages({ path: { id: sessionID } });
    const msgs = normalizeSDKResponse(messagesCheck, [], {
      preferResponseOnMissingData: true
    });
    const currentMsgCount = msgs.length;
    if (currentMsgCount === 0) {
      stablePolls = 0;
      lastMsgCount = 0;
      if (!sawActiveStatus && Date.now() - pollStart >= PROMPT_ACCEPTANCE_TIMEOUT_MS) {
        throw new Error(`Prompt was not durably accepted by OpenCode for session ${sessionID}.`);
      }
      continue;
    }
    if (currentMsgCount > 0 && currentMsgCount === lastMsgCount) {
      stablePolls++;
      if (stablePolls >= STABILITY_REQUIRED) {
        log4(`[call_omo_agent] Session complete, ${currentMsgCount} messages`);
        break;
      }
    } else {
      stablePolls = 0;
      lastMsgCount = currentMsgCount;
    }
  }
  if (Date.now() - pollStart >= MAX_POLL_TIME_MS) {
    log4(`[call_omo_agent] Timeout reached`);
    throw new Error("Agent task timed out after 5 minutes.");
  }
}

