// packages/omo-opencode/src/features/tmux-subagent/session-ready-waiter.ts
async function waitForSessionReady(params) {
  const startTime = Date.now();
  while (Date.now() - startTime < SESSION_READY_TIMEOUT_MS) {
    try {
      const statusResult = await params.client.session.status({ path: undefined });
      const allStatuses = parseSessionStatusResponse(statusResult);
      const sessionStatus = allStatuses[params.sessionId]?.type;
      if (isAttachableSessionStatus(sessionStatus)) {
        log4("[tmux-session-manager] session ready", {
          sessionId: params.sessionId,
          status: sessionStatus,
          waitedMs: Date.now() - startTime
        });
        return true;
      }
    } catch (error) {
      log4("[tmux-session-manager] session status check error", { error: String(error) });
    }
    await new Promise((resolve) => {
      setTimeout(resolve, SESSION_READY_POLL_INTERVAL_MS);
    });
  }
  log4("[tmux-session-manager] session ready timeout", {
    sessionId: params.sessionId,
    timeoutMs: SESSION_READY_TIMEOUT_MS
  });
  return false;
}

