init_logger2();
import { z as z72 } from "zod";
var sessionToolPermissionsSchema = z72.object({
  permission: z72.array(z72.object({
    permission: z72.string(),
    pattern: z72.string(),
    action: z72.enum(["allow", "ask", "deny"])
  })).optional()
});
